const seed={org:{id:'org_demo',name:'My Orbit workspace',plan:'Free demo'},user:{name:'',email:'',role:'Owner',goal:'',useCase:''},courses:[],tasks:[],timeBlocks:[],grading:{},latePolicy:{dailyPenalty:5,maxPenalty:100},focus:0,onboarded:false,tourComplete:false,tourStarted:false,procrastination:{enabled:false,days:3}};
let state=JSON.parse(localStorage.getItem('orbit_demo_v2')||'null')||seed;if(state.org?.name)state.org.name=state.org.name.replace(/workspace$/i,'Workspace');state.timeBlocks ||= [];state.grading ||= {};state.latePolicy ||= {dailyPenalty:5,maxPenalty:100};let view=location.hash.replace('#/','')||'landing';let timer={seconds:25*60,running:false,interval:null,preset:25,mode:'focus',custom:false};
